SELECT
    ,
    pr.product_name AS productName,
    pr.product_code AS productCode,
    sk.spec_text AS specText,
    w.warehouse_name AS warehouseName,
    eu.nickname AS userName


    l.is_deleted = 0


        AND l.sku_id = #{q.skuId}


        AND sk.product_id = #{q.productId}


        AND l.warehouse_id = #{q.warehouseId}


        AND l.change_type = #{q.changeType}



ORDER BY l.id DESC
